"col-md-4"><label class="form-check mt-2"><input class="form-check-input" type="checkbox" name="disabled" value="1" <?= ! empty($field['disabled']) ? 'checked' : '' ?>><span class="form-check-label">Inactiva</span></label></div></div><div class="d-flex justify-content-end gap-2 mt-4"><a class="btn btn-outline-secondary" href="#">Cancelar</a><button class="btn btn-primary">Guardar cancha</button></div></div></form></section></div><?php endforeach; ?><script>document.addEventListener('click',function(event){var link=event.target.closest('a[href*="/canchas/"]');if(!link)return;var match=link.getAttribute('href').match(/canchas\/(\d+)/);if(!match)return;event.preventDefault();window.location.hash='field-modal-'+match[1];});</script>
