<script>document.querySelectorAll('.field-inline-modal__panel .card-body').forEach(function(body){const actions=body.querySelector('.d-flex.justify-content-end');if(!actions)return;const box=document.createElement('section');box.className='field-inline-nocturnal';box.innerHTML='<strong>Precio nocturno</strong><span class="field-inline-nocturnal__time"><?= esc($nocturnalLabel) ?></span><small>Desde este horario se aplica el precio nocturno configurado para esta cancha según la regla global del administrador.</small>';actions.parentNode.insertBefore(box,actions);});</script>
<script>function mostrarDuracionHsMinutos(root){(root||document).querySelectorAll('input[name="duration_minutes"]:not([data-hs-minutos])').forEach(function(input){const total=Math.max(0,parseInt(input.value||'0',10)||0),wrap=document.createElement('div');wrap.className='duration-hm';wrap.innerHTML='<input class="form-control" type="number" name="duration_hours" min="0" max="23" value="'+Math.floor(total/60)+'" aria-label="Horas"><span>h</span><input class="form-control" type="number" name="duration_minutes_part" min="0" max="59" step="15" value="'+(total%60)+'" aria-label="Minutos"><span>min</span>';input.parentElement.firstChild.nodeValue='Duración del turno';input.dataset.hsMinutos='1';input.replaceWith(wrap);});}mostrarDuracionHsMinutos(document);</script>
